namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage2; class toutiao extends cloudStorage2 { var $host = 'p.pstatp.com'; public function init() { $this->silent_scanning = $this->options->cloud_storage_toutiao_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_toutiao_delete_attachment_after_synced; } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; $name = basename($source_path); $preg = preg_match('/(.*?)\\.[A-Za-z0-9]+/', $name, $match); if ($preg) $name = $match[0]; $bits = file_get_contents($source_path); $type = mime_content_type($source_path); $mimeType = empty($type) ? 'application/octet-stream' : $type; $postDatas = array( array( 'name' => 'file_id', 'value' => 0 ), array( 'name' => 'image', 'filename' => $name, 'value' => $bits ) ); $headers = array(); array_push($headers, "User-Agent: {$this->user_agent}"); array_push($headers, 'Referer: http://tuchuang.cnzzla.com/index.html'); array_push($headers, 'Origin: http://tuchuang.cnzzla.com'); list($post_data, $headers) = $this->getFormData($source_path, $mimeType, $postDatas, $headers); $target_url = 'https://image.kieng.cn/upload.html?type=tt'; $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $target_url); curl_setopt($ch, CURLOPT_HTTPHEADER, $headers); curl_setopt($ch, CURLOPT_USERAGENT, $this->user_agent); curl_setopt($ch, CURLOPT_POST, 1); curl_setopt($ch, CURLOPT_POSTFIELDS, $post_data); curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false); curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, false); $result = curl_exec($ch); curl_close($ch); $result = json_decode($result, true); if ($result && $result['code'] == 200) return preg_replace('/jpe$/i', 'jpg', $result['data']['url']); else do_action( 'qqworld-collector-log', $this->log_id, 'toutiao failed: ', print_r($result, true) ); return false; } } ?>